package com.dy.artisan3d.data.mapperimport com.dy.artisan3d.data.model.artisan.article.ArtisanArticleDtoimport com.dy.artisan3d.data.model.artisan.article.ArtisanArticleTranslationDtoimport com.dy.artisan3d.domain.model.artisan.ArtisanArticlefun ArtisanArticleDto.toDomain(targetLang: String): ArtisanArticle {    val translation = translations[targetLang]        ?: translations.values.firstOrNull()        ?: ArtisanArticleTranslationDto()    val fullHtml = translation.text ?: ""    // HTML teglarni olib tashlash va qisqa matn yaratish    val plainText = fullHtml.replace(Regex("<[^>]*>"), "")        .replace("&nbsp;", " ")        .trim()    val shortDescription = if (plainText.length > 120) {        plainText.take(120) + "..."    } else {        plainText    }    return ArtisanArticle(        id = id,        slug = slug,        author = translation.author ?: "Unknown",        title = translation.title ?: "No Title",        shortDesc = shortDescription,        contentHtml = translation.text ?: ""    )}